import {releaseAlternate,tickAlternateFields,alternateOnHit} from './alternate-skills.mjs';
import {canPickupDrop,useRecoveryDrop} from './campaign-pickups.mjs';
import {recordRunKill,recordRunItem} from './campaign-rewards.mjs';
import {grantPetXP} from './campaign-pet-data.mjs';
import {heroStats,grantXP,addItem} from './campaign-profile.mjs';
import {skillById,stageLoot,experience,SOLO_KILL_XP,SOLO_BALANCE} from './campaign-growth-data.mjs';
import {groundTarget} from './targeting.mjs?v=20261030-duel12';
import {advanceDaily} from './daily-quests.mjs';
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export function soloActivity(w,metric,amount=1){const c=w.campaign;if(c?.progression&&!['complete','defeat'].includes(c.state)&&advanceDaily(c.progression,metric,amount))c.dirty=true;}
export function syncSoloStats(w,initial=false){const c=w.campaign;if(!c?.progression)return;const s=heroStats(c.progression,w.hero),p=w.player,dh=s.maxHp-p.maxHp,dm=s.maxMp-(p.maxMp||0);p.maxHp=s.maxHp;p.maxMp=s.maxMp;p.hp=initial?s.maxHp:p.hp<=0?0:Math.min(s.maxHp,p.hp+(c.noStatHealOnce?0:Math.max(0,dh)));p.mp=initial?s.maxMp:Math.min(s.maxMp,(p.mp||0)+(c.noStatHealOnce?0:Math.max(0,dm)));c.stats=s;c.noStatHealOnce=false;}
export function soloSpec(w,key,base){const c=w.campaign;if(!c?.progression||key==='attack')return base;const s=skillById(c.progression.heroes[w.hero].slots[key]);if(!s)return null;const rank=c.progression.heroes[w.hero].skills[s.id]||0;return {...base,...(s.column?{duration:s.row===2?.9:.55,release:s.row===2?.4:.2}:{}),cd:(s.cd??base.cd)*(1-.02*rank),name:s.name,soloSkill:s};}
export function soloPay(w,key,recast,spec){const c=w.campaign;if(!c?.progression)return true;if(key==='attack')return true;if(!spec?.soloSkill)return false;if(recast)return true;const cost=spec.soloSkill.mana;if(w.player.mp<cost){c.notice=c.stats.manaRegen>0?'法力不足 · 收集灵露或等待被动回复':'法力不足 · 拾取灵露，或学习回蓝被动';c.noticeUntil=w.time+1.4;return false;}w.player.mp-=cost;return true;}
export function soloDamage(w,amount,{castId,soloSkill}={}){const c=w.campaign;if(!c?.progression)return amount;const id=soloSkill||c.castSkills?.[castId]||w.campaignDamageSkill,rank=c.progression.heroes[w.hero].skills[id]||0;const skillScale=skillById(id)?.row===0?.58:skillById(id)?.row===1?.68:skillById(id)?.row===2?.78:1;let result=amount*c.stats.power*(1+rank*.08)*skillScale;const random=c.random||Math.random;if(random()<c.stats.crit)result*=c.stats.critDamage;return Math.max(1,Math.round(result));}
export function soloOnHit(w,t,castId,source,api){const c=w.campaign;if(!c?.progression)return;alternateOnHit(w,t,skillById(c.castSkills[castId]),castId,source,c,api);}
export function soloRelease(w,cast,api){const s=cast.soloSkill;if(w.campaign?.progression&&!cast.variant)soloActivity(w,cast.key==='attack'?'attacks':'skills');if(!w.campaign?.progression||!s?.column)return false;return releaseAlternate(w,cast,api,{fields:w.campaign.soloFields,rank:w.campaign.progression.heroes[w.hero].skills[s.id]||0});}

function drop(w,item,x,y,flags={}){const c=w.campaign,surface=groundTarget(w,x,y-2);c.drops.push({id:'drop-'+(++w.serial),item:{...item},x,y:surface?.y??w.floor,born:w.time,...flags});}
export function soloTick(w,dt,api){const c=w.campaign;if(!c?.progression)return;const p=w.player,profile=c.progression;syncSoloStats(w);if(p.hp>0){p.mp=Math.min(p.maxMp,p.mp+dt*c.stats.manaRegen);p.hp=Math.min(p.maxHp,p.hp+dt*c.stats.regen);}
 c.soloFields=tickAlternateFields(w,c.soloFields,api);
 for(const t of w.targets){if(t.hp>0||t.rewarded||!t.enemyKind||t.owner||t.egg||t.baby||!t.killedByPlayer)continue;t.rewarded=true;if(t.enemyKind.startsWith('B')){if(!c.bossLooted){c.bossLooted=true;soloActivity(w,'bosses');if(w.companion?.hp>0)grantPetXP(profile,w.companion.recordId,25);const drops=stageLoot(c.stage.id,c.random);drops.forEach((item,i)=>drop(w,item,t.x+(i-2)*42,w.floor));if(!profile.firstTickets.includes(c.stage.id)||(c.random||Math.random)()<.5)drop(w,{type:'ticket',count:1},t.x+120,w.floor,{firstTicket:!profile.firstTickets.includes(c.stage.id),stage:c.stage.id});if(c.stage.id===1&&!profile.choiceClaimed)drop(w,{type:'heroChoice',count:1},t.x-145,w.floor,{choice:true});}}
  else{soloActivity(w,'minions');const before=experience(profile.heroes[w.hero].exp).level;const coins=c.stage.killCoins||6;profile.coins+=coins;recordRunKill(c,w.hero,coins);grantXP(profile,w.hero,SOLO_KILL_XP);if(w.companion?.hp>0)grantPetXP(profile,w.companion.recordId,5);c.rewardCount++;if(experience(profile.heroes[w.hero].exp).level>before){c.notice='等级提升 · Lv.'+experience(profile.heroes[w.hero].exp).level;c.noticeUntil=w.time+2;syncSoloStats(w);}if(c.recoveryDrops<2&&(c.random||Math.random)()<SOLO_BALANCE.recoveryDropChance){drop(w,{type:c.recoveryDrops%2?'mana':'health',count:1},t.x,t.y,{recovery:true});c.recoveryDrops++;}}c.dirty=true;}
}
export function pickupSolo(w){const c=w.campaign;if(!c?.progression)return 0;let count=0,bagged=0;for(const d of c.drops){if(!canPickupDrop(w,d))continue;if(d.choice&&c.progression.choiceClaimed){d.picked=true;continue;}if(d.firstTicket&&c.progression.firstTickets.includes(d.stage)){d.picked=true;continue;}const recovery=useRecoveryDrop(w,d.item);if(recovery){if(!recovery.amount)continue;d.picked=true;count++;continue;}const obtained=addItem(c.progression,d.item);recordRunItem(c,{...(obtained||d.item),count:d.item.count||1});if(d.choice)c.progression.choiceClaimed=true;if(d.firstTicket)c.progression.firstTickets.push(d.stage);d.picked=true;count++;bagged++;}if(count){soloActivity(w,'pickups',count);c.dirty=true;if(bagged){c.notice=`拾取${bagged}件物品 · 已放入背包`;c.noticeUntil=w.time+2;}}c.drops=c.drops.filter(d=>!d.picked);return count;}
